  background: #5a8aff;
}

.auth-form {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.auth-input {
  padding: 0.65rem 0.85rem;
  font-size: 1rem;
  border-radius: 8px;
  border: 1px solid #3a3a3e;
  background: #0f0f10;
  color: #ececec;
}

.auth-input:focus {
  outline: none;
  border-color: #4a7cff;
}

.auth-card a {
  color: #4a7cff;
  text-decoration: none;
}
.auth-card a:hover {
  text-decoration: underline;
}
