.auth-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #0f0f10;
  padding: 1.5rem;
}

.auth-card {
  background: #1a1a1c;
  border: 1px solid #2a2a2e;
  border-radius: 12px;
  padding: 2rem;
  max-width: 28rem;
  width: 100%;
  color: #ececec;
  font-family: system-ui, sans-serif;
}

.auth-title {
  font-size: 1.25rem;
  font-weight: 600;
  margin: 0 0 1rem;
}

.auth-msg {
  font-size: 1rem;
  line-height: 1.5;
  margin: 0 0 0.75rem;
}

.auth-sub {
  font-size: 0.85rem;
  color: #9a9a9e;
  margin: 0 0 1.25rem;
}

.auth-status {
  font-size: 0.95rem;
  color: #b8b8bc;
  margin: 1rem 0;
}

.auth-error {
  color: #ff7a7a;
  font-size: 0.95rem;
  margin: 0.75rem 0;
}

.auth-btn {
  display: block;
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  border-radius: 8px;
  border: 1px solid #3a3a3e;
  background: #242428;
  color: #ececec;
  cursor: pointer;
  margin-top: 0.5rem;
  transition: background 120ms ease;
}

.auth-btn:hover {
  background: #2c2c30;
}

.auth-btn-primary {
  background: #4a7cff;
  border-color: #4a7cff;
  color: #fff;
  font-weight: 500;
}

.auth-btn-primary:hover {
  background: #5a8aff;
}

.auth-form {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.auth-input {
  padding: 0.65rem 0.85rem;
  font-size: 1rem;
  border-radius: 8px;
  border: 1px solid #3a3a3e;
  background: #0f0f10;
  color: #ececec;
}

.auth-input:focus {
  outline: none;
  border-color: #4a7cff;
}

.auth-card a {
  color: #4a7cff;
  text-decoration: none;
}
.auth-card a:hover {
  text-decoration: underline;
}

.auth-screen {
  background: #080808;
  color: #fff;
  font-family: 'Geist', system-ui, sans-serif;
  padding: 2rem;
}

.auth-screen__content {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  max-width: 56rem;
}

.auth-screen__title {
  font-weight: 500;
  font-size: clamp(2rem, 6vw, 4.5rem);
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin: 0 0 0.4em;
}

.auth-screen__sub {
  font-weight: 400;
  font-size: clamp(1rem, 2.2vw, 1.75rem);
  line-height: 1.4;
  color: #ffffff;
  opacity: 0.7;
  margin: 0;
  max-width: 28ch;
}

.auth-screen__btn {
  background: #101010;
  color: #fff;
  font-family: 'Inter', system-ui, sans-serif;
  font-weight: 600;
  font-size: clamp(1.5rem, 2.1vw, 1.7rem);
  padding: clamp(1.275rem, 2.55vw, 1.65rem) clamp(3.75rem, 7.5vw, 6rem);
  border: none;
  border-radius: 21px;
  cursor: pointer;
  transition: background 120ms ease, transform 120ms ease;
  margin-top: clamp(2rem, 5vw, 4rem);
}
.auth-screen__btn:hover {
  background: #1a1a1a;
}
.auth-screen__btn:active {
  transform: translateY(1px);
}

