            </button>
            <button
              type="button"
              className="auth-screen__link"
              onClick={() => navigate('/')}
            >
              Decline
            </button>
          </form>
        )}

        {phase === 'submitting' && <p className="auth-screen__status">Authorizing…</p>}
      </div>
    </div>
  );
}

