import { useLocation, useNavigate } from 'react-router-dom';
import { MCP_SERVER_URL } from '../config';
import { usePasskeyAuth } from '../hooks/usePasskeyAuth';
import './AuthPages.css';

// Phases:
//   loading      – fetching client info
