  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #0f0f10;
  padding: 1.5rem;
}

.auth-card {
  background: #1a1a1c;
  border: 1px solid #2a2a2e;
  border-radius: 12px;
  padding: 2rem;
  max-width: 28rem;
  width: 100%;
  color: #ececec;
  font-family: system-ui, sans-serif;
}

.auth-title {
  font-size: 1.25rem;
  font-weight: 600;
  margin: 0 0 1rem;
}

.auth-msg {
  font-size: 1rem;
  line-height: 1.5;
  margin: 0 0 0.75rem;
}

