  font-size: 0.85rem;
  color: #9a9a9e;
  margin: 0 0 1.25rem;
}

.auth-status {
  font-size: 0.95rem;
  color: #b8b8bc;
  margin: 1rem 0;
}

.auth-error {
  color: #ff7a7a;
  font-size: 0.95rem;
  margin: 0.75rem 0;
}

.auth-btn {
  display: block;
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  border-radius: 8px;
  border: 1px solid #3a3a3e;
  background: #242428;
  color: #ececec;
  cursor: pointer;
  margin-top: 0.5rem;
  transition: background 120ms ease;
}

